            elif self._align[field] == "r":
                bits.append(options["horizontal_char"] * (field_width - 2) + 
                           options["horizontal_align_char"] + options["horizontal_char"])
            else:  # center alignment
                bits.append(options["horizontal_char"] + options["horizontal_align_char"] + 
